"""TARGET macroeconomics reviews preserving original alternatives and intent."""

REVIEWS = []


def mc(key, answer, prompt, proof, assumptions, finding="", claims="", kind="multiple_choice"):
    """Record one inspected TARGET question with scoped supporting reasoning."""
    REVIEWS.append({
        "id": key, "answer": answer, "clean_prompt": prompt,
        "claim_ids": claims.split(), "review_note": proof,
        "source_finding": finding, "answer_kind": kind,
        "concept_review": {"derivation": proof, "assumptions": assumptions,
                           "basis": "explicit_conditions_and_independent_reasoning",
                           "current_law_claim": False} if not claims else None,
    })


mc("S3C8T01-CORE", "③", "물가가 고정되어 있다는 전제에서 재화시장과 화폐시장의 동시균형으로 국민소득과 이자율을 분석하는 전통적 총수요모형은? ① Demand-Supply 모형 ② AD-AS 모형 ③ IS-LM 모형 ④ AD-AS 모형과 IS-LM 모형", "책의 정답③과 일치한다. IS-LM은 주어진 물가의 실질화폐량을 놓고 재화·화폐시장 균형을 함께 구한다. AD-AS는 물가와 산출을 함께 분석하는 체계다.", "TARGET P3 402쪽; 전통적 고정가격 모형.", "원래 네 모형 보기와 정답을 유지하고 재화·화폐 동시균형을 명시해 일반적인 수요공급모형과 구별했다.", "L330")
mc("S3C8T02-CORE", "②", "전통적 고정가격 IS-LM 모형에서 IS곡선 설명 중 틀린 것은? 소비는 가처분소득에 증가하고 투자는 금리에 감소한다고 한다. R은 금리, Y는 실질소득이다. ① 재화시장 균형을 이루는 R과 Y의 조합이다. ② R이 하락하면 총수요와 Y가 증가하므로 IS곡선은 우상향한다. ③ 정부지출G와 조세T는 외생변수다. ④ 주어진 외생변수 아래 R·Y 변화는 곡선 위 이동이고, 총수요에 영향을 주는 외생변수 변화는 곡선을 이동시킨다.", "②의 앞부분은 금리하락·소득증가라는 반대방향 관계이므로 결론은 우하향이다. 책의 정답②를 유지한다. ①균형궤적,③외생재정변수,④곡선 위 이동/이동 구분은 해당모형에서 타당하다.", "TARGET P3 404쪽; 안정적 소비승수·금리민감 투자.", "원문④의 R,Y 이외 아무 변수나 곡선을 이동시킨다는 무제한 표현을 총수요에 영향을 주는 외생변수로만 명확히 했다. 네 보기 판정 의도 유지.", "L330")
mc("S3C8T02-SUP-01", "③", "우하향 IS와 우상향 LM을 갖는 전통적 IS-LM 모형에서, 다른 조건이 같을 때 틀린 것은? ① 정부지출G 증가는 실질소득Y와 금리R을 높인다. ② 조세T 감소는 Y와 R을 높인다. ③ 명목화폐공급M 증가는 Y와 R을 높인다. ④ 물가P 하락은 Y를 높이고 R을 낮춘다.", "①②는 IS 우측 이동이다. ③④는 M/P 증가로 LM이 우측 이동하므로 Y상승·R하락이다. 따라서 R상승을 주장한③이 틀리고 책의 정답과 일치한다. 예컨대 Y=A-bR, kY-hR=M/P에서 b,k,h>0이면 dY/d(M/P)>0,dR/d(M/P)<0이다.", "TARGET P3 406쪽; 통상 기울기·정책별 다른 변수 고정.", "원래 네 정책과 방향을 모두 유지하고 유동성함정 등 예외구간을 배제하는 기울기 조건만 명시했다.", "L330")
mc("S3C8T02-SUP-02", "③", "소비는 가처분소득에 증가하고 정부지출 등 다른 조건은 일정하다고 한다. IS의 계획총지출 C+I+G+X-IM을 증가시키는 요인이 아닌 것은? ① 소비증가 ② 투자증가 ③ 세율인상 ④ 수출증가", "①②④는 총지출의 양의 항 증가다. 소득 일정에서 세율인상은 가처분소득과 소비를 감소시키므로③이다. 책의 정답을 유지한다.", "TARGET P3 406쪽; 소득 고정에서 세율의 직접효과·양의 한계소비성향.", "해설의 T(세율) 혼용을 피하고 수입IM과 통화M을 구분했다. 원문 보기와 정답을 그대로 유지했다.")
mc("S3C8T03-CORE", "④", "전통적 고정가격 IS-LM에서 금리상승을 통한 민간투자 감소라는 구축효과 설명 중 적절하지 않은 것은? ① 확대재정은 소득을 늘리는 한편 금리상승으로 민간투자를 줄여 소득증가 효과를 약화시킬 수 있다. ② 완전구축이면 확대재정의 소득증가 효과가 없다. ③ LM이 수평인 구간에서는 확대재정에 따른 금리상승이 없어 이 경로의 구축효과가 없다. ④ 통상 우상향 LM 구간의 확대통화는 금리를 상승시켜 부분구축을 일으킨다.", "①은 재정확대의 금리경로,②는 완전상쇄의 정의,③은 금리고정이라 해당경로 상쇄0이다. ④통화확대는 금리를 낮추므로 책의 정답④가 맞다. Y=A-bR과 kY-hR=M/P에서 실질통화증가가 R을 낮춤을 확인한다.", "TARGET P3 407쪽; 다른 경로가 아닌 전통적 금리경로의 구축효과.", "원문 반감은 정확히 절반이라는 뜻이 아닌 약화로 정리했다. 원문 네 보기·정답 유지, 정책효과 극대화는 해당 모형의 금리경로로 한정했다.", "L330")
mc("S3C8T03-SUP-01", "③", "전통적 고정가격 IS-LM의 유동성함정에서 LM이 수평이고, 재정확대 후에도 그 구간에 머문다. 확대재정에 따른 금리상승 경로의 구축효과는? ① 완전구축효과 ② 부분구축효과 ③ 무구축효과 ④ 정답 없음", "수평 LM에서는 dR=0이므로 금리상승에 따른 투자감소도0이다. 따라서 무구축인③이며 책의 정답·보기와 일치한다.", "TARGET P3 408쪽; 수평구간 유지·금리경로 한정.", "책의 유동성함정 구간이라는 전제를 명시했으며 다른 경로나 현실의 모든 재정효과로 확장하지 않는다.")

mc("S3C8T04-CORE", "②", "전통적 IS-LM의 유동성함정 설명 중 가장 거리가 먼 것은? ① 매우 낮은 금리에서 화폐보유 기회비용이 작아 추가 화폐가 금리하락 없이 흡수될 수 있다. ② 그 구간의 LM은 수직이며 화폐수요의 금리민감도가0이다. ③ 수평구간에 머무르면 정부지출확대는 금리불변 상태에서 소득을 늘릴 수 있다. ④ 물가하락으로 실질잔액이 증가해 소비를 자극하는 효과까지 허용하면, 재정확대 외의 수요확대 경로도 논의할 수 있다.", "유동성함정은 추가 화폐가 금리하락 없이 흡수되는 수평 LM 구간이므로②가 틀리다. ①③이 그 특징이며④는 실질잔액효과라는 별도 경로의 이론적 가능성이다. TARGET 정답②를 유지한다.", "TARGET P3 409쪽 네 보기 및 리치먼드연은 이론사 자료.", "원문①의 실제 보유액이 무한대로 폭발한다는 표현을 완전탄력적 수요 설명으로 수정했다.④의 가격신축성만으로 재정정책 독자효과가 반드시 상실된다는 단정을 별도경로 가능성으로 한정했다. 네 보기의 주제·정답 유지.", "L331")
mc("S3C8T04-SUP-01", "②", "물가하락이 경제주체의 실질잔액을 늘리고 소비·총수요를 증가시켜 IS를 우측 이동시킬 수 있다는 이론적 경로는? ① 깁슨의 패러독스 ② 고전학파의 피구효과 ③ 피셔효과 ④ 리카도의 불변정리", "실질잔액 증가를 통한 소비자극은 피구효과이므로②다. TARGET의 설명·정답과 일치한다. 현실에서 반드시 유동성함정을 탈출한다는 보장과는 구별한다.", "TARGET P3 411쪽; 원문 네 이론 선택지 유지.", "원문 부가해설의 물가수준과 인플레이션율 혼용 및 깁슨역설이 더는 역설이 아니라는 단정은 이 정답근거로 사용하지 않는다. 보기의 실질잔액 경로로 판정했다.", "L331")
mc("S3C8T05-CORE", "③", "화폐공급이 외생적으로 주어진 케인즈 유동성선호설에 대한 설명 중 틀린 것은? ① 주어진 소득·물가에서 화폐시장의 수요·공급으로 금리를 설명한다. ② 소득이 증가하거나 금리가 하락하면 화폐수요가 증가한다. ③ 화폐시장과 무관하게 시간선호와 자본의 한계생산성만으로 금리를 설명하는 이론이다. ④ 화폐공급이 일정하면 화폐수요 변화에 따라 균형금리가 변한다.", "이 모형은 외생 화폐공급과 소득·금리에 의존하는 화폐수요의 균형으로 금리를 설명하므로 실물요인만의 이론이라고 한③이 틀리다. TARGET 정답③ 및 각 보기의 구분 의도를 유지한다.", "TARGET P3 412쪽; 주어진 소득과 물가의 화폐시장 분석.", "원문④의 총공급·총수요 OCR을 화폐공급·화폐수요로 복원했다.①은 IS-LM 전체에서 실물시장이 전혀 영향을 주지 않는다는 뜻으로 읽히지 않게 분석범위를 명시했다.", "L330")
mc("S3C8T07-CORE", "②", "TARGET 그림을 문자로 복원한다. 세로축R·가로축M이며 공급은 수직선 Ms0에서 오른쪽 Ms1로 증가한다. a=(Ms0,Md0), b=(Ms1,Md0), c=(Ms1,Md1), d=(Ms1,Md2)이고 Md1은 소득증가, Md2는 추가 물가·기대인플레이션 효과를 나타낸다. 소득효과에 해당하는 이동은? ① a→b ② b→c ③ c→d ④ a→c", "통화공급증가만의 a→b와 구분하여 소득증가로 화폐수요가 Md0에서 Md1로 이동하는 구간은 b→c다. 그림과 책의 정답②를 직접 대조했다.", "TARGET P3 417쪽 그림 직접 판독; diagram_review/P3_417.png. 그림에 부여된 단계에 한정.", "OCR에서 빠진 그래프 축·수직공급선·네 교점을 복원했다. 원문 아래 예시의3~4개월·1년·1년6개월을 보편적인 정책파급 시차로 승인하지 않는다.", "L330")
mc("S3C8T08-SUP-01", "④", "같은 조사대상·연령기준의 고용통계에서 산식이 잘못된 것은? ① 생산가능인구=경제활동인구+비경제활동인구 ② 경제활동인구=취업자+실업자 ③ 경제활동참가율=경제활동인구/생산가능인구×100 ④ 실업률=실업자/생산가능인구×100", "실업률 분모는 경제활동인구이므로④가 틀리다. 나머지는 정의와 일치한다. 원본 P3 421쪽 이미지를 읽어 OCR에서 누락된③분수도 복원했고 정답④를 유지했다.", "TARGET P3 421쪽 이미지 직접 확인; 공통조사대상.", "네 보기·정답을 그대로 보존하고③의 분자/분모 OCR만 복원했다. 원문 분류도의 학생·주부 등 이름만으로 모든 개인을 비경제활동인구로 단정하지 않는다.", "L332")
mc("S3C8T08-SUP-02", "②", "취업자700명, 실업자100명, 생산가능인구1,000명이다. 실업률과 경제활동참가율은 순서대로? ①10%,70% ②12.5%,80% ③10%,80% ④12.5%,70%", "경제활동인구=700+100=800명. 실업률=100/800×100=12.5%, 참가율=800/1000×100=80%로②다. 원문 수치·보기·정답 모두 유지.", "TARGET P3 421쪽 원문 이미지 확인; 동일조사 범위.", "해설 OCR의0.25·25%·0.5를 원본 이미지의0.125·12.5%·0.8로 바로잡았다.", "L332")

mc("S3C8T06-CORE", "④", "다음 설명에 가장 부합하는 수익률곡선 이론은? 장기수익률을 예상 단기금리와 기간프리미엄으로 설명한다. 투자자는 선호하는 만기 구간이 있으나 충분한 보상이 있으면 다른 만기로 이동하여, 기대요인과 만기별 수급을 함께 고려한다. ① 불편기대이론 ② 유동성선호이론 ③ 시장분할이론 ④ 특정시장선호이론", "선호 만기를 가지면서 보상에 따라 만기간 이동할 수 있다는 조건이 특정시장선호(선호서식지) 이론을 구별하므로④다. 원문④와 기대이론·시장분할 절충이라는 설명을 유지한다.", "TARGET P3 415쪽.", "기간프리미엄이라는 말 하나만으로②와④를 배타적으로 구별하지 않도록 원문 둘째 조건인 만기별 선호·대체관계를 풀어 명시했다. 네 이론 보기와 정답번호 유지.", "L333")
mc("S3C8-ADD-01", "①", "우하향 IS·우상향 LM의 전통적 고정가격 모형에서 다른 조건이 같을 때 실질국민소득을 증가시키지 않는 외생변수 변화는? 물가변화는 주어진 가격수준을 달리하는 비교정태로 본다. ① 물가상승 ② 정부지출증가 ③ 통화량증가 ④ 조세감면", "①은 M/P를 줄여 LM을 좌측으로 이동시켜 소득을 줄인다.②④는 IS 우측 이동,③은 LM 우측 이동으로 소득을 늘린다. 원문 정답① 및 선택지를 유지한다.", "TARGET P3 427쪽; 정상 기울기·비교정태.", "원문②의 '정부지출'은 해설 의도에 맞춰 증가를 명시했다. 고정물가 모형에서 물가의 비교정태라는 점을 구분했다.", "L330")
mc("S3C8-ADD-02", "②", "화폐수요함수는 일정하고 통상 우상향 LM을 가정한다. 다른 조건이 같을 때 LM을 우측으로 이동시키는 요인이 아닌 것은? ① 명목통화량증가 ② 물가상승 ③ 실질통화량증가 ④ 물가하락", "①③④는 실질공급 M/P를 증가시킨다.②는 M/P를 줄여 LM을 좌측 이동시키므로②다. 원문 네 보기·정답 유지.", "TARGET P3 427쪽; 물가양수·명목공급 고정 비교.", "원문①의 통화는 명목통화,③은 실질통화임을 분명히 했다.", "L330")
mc("S3C8-ADD-03", "②", "물가하락에 따른 실질잔액 증가가 소비를 늘려 유동성함정 탈출을 설명할 수 있다는 고전학파의 논리는? ① 피셔효과 ② 피구효과 ③ 리카르도의 불변정리 ④ 합리적 기대학파의 정책무용성 정리", "실질잔액이 소비를 자극하는 경로인 피구효과이므로②다. TARGET의 네 보기와 정답을 유지한다.", "TARGET P3 427쪽.", "유동성함정 탈출이 현실에서 반드시 보장된다는 뜻이 아닌 해당 이론의 경로를 묻도록 명시했다.", "L331")
mc("S3C8-ADD-06", "①", "장·단기 채권을 완전대체관계로 보고 순수한 기대단기금리 경로로 기간구조를 설명하는 이론은? ① 불편기대이론 ② 유동성선호이론 ③ 시장분할이론 ④ 특정시장선호이론", "완전대체·기간프리미엄 없는 순수기대 관점은①이다. 선호서식지의 불완전 대체와 구분되며 TARGET 정답·보기 유지.", "TARGET P3 428쪽.", "기대가설의 여러 변형과 구별하도록 순수 기대이론 범위를 명시했다.", "L333")
mc("S3C8-ADD-10", "④", "통화량2,500조, 명목GDP2,000조, 실질GDP1,250조다. 같은 기간 통화유통속도와 GDP디플레이터(기준1인 비율)를 순서대로 고르면? ①0.63,0.80 ②0.63,1.25 ③0.80,1.25 ④0.80,1.60", "유통속도=명목GDP/통화량=2000/2500=.8. 디플레이터 비율=명목/실질GDP=2000/1250=1.6이므로④다. 기준100 지수로 표시하면160이다. 원문 데이터·네 보기·정답 유지.", "TARGET P3 430쪽; 디플레이터 비율 기준1, 통화량과 GDP 기간대응.", "원문1.60은 기준1인 비율임을 명시해 통상 기준100지수160과 혼동하지 않게 했다.")


def short(key, answer, prompt, proof, assumptions, finding="", claims=""):
    """Keep TARGET short-answer format with the same evidence requirements."""
    mc(key, answer, prompt, proof, assumptions, finding, claims, kind="text")


short("NOTE-S3C8-Q001", "IS곡선, LM곡선", "전통적 IS-LM 모형은 재화시장 균형인 ( )과 화폐시장 균형인 ( )의 교점에서 두 시장의 동시균형이 이루어진다고 본다. 빈칸을 순서대로 쓰시오.", "재화시장은IS, 화폐시장은LM이다. NOTE79쪽 원답 두 곡선과 일치한다.", "전통적 고정가격 모형.", "원문의 경제전체균형은 노동시장 완전고용까지 보장하는 뜻이 아니므로 두 시장 동시균형으로 명확히 했다.", "L330")
short("NOTE-S3C8-Q002", "R, Y; G, T", "IS의 기본식 Y=C(Y-T)+I(R)+G에서 금리와 소득을 내생변수로, 재정지출과 조세를 외생변수로 둔다. 각 두 변수 기호를 순서대로 쓰시오.", "금리R·소득Y, 정부지출G·조세T다. NOTE79쪽 원답과 일치한다.", "주어진 모형의 내생·외생 구분.", "다른 거시모형까지 동일 분류를 일반화하지 않도록 IS 기본모형 범위를 명시했다.", "L330")
short("NOTE-S3C8-Q003", "R, Y; P, M", "LM의 기본식 M/P=L(Y,R)에서 금리·소득을 내생변수, 물가·명목통화량을 외생변수로 둔다. 각 두 변수의 기호를 순서대로 쓰시오.", "R,Y와 P,M이다. NOTE79쪽 원답 그대로이며 물가P와 명목통화M의 역할을 구별한다.", "고정물가·외생통화의 전통적 모형.", "OCR 기호를 복원하고 모형의 변수 구분을 명시했다.", "L330")
short("NOTE-S3C8-Q004", "X", "IS-LM 곡선에서 내생변수 R,Y의 값 자체가 곡선의 기울기를 결정하고, 외생변수는 곡선 위치에만 영향을 준다. O/X?", "기울기는 소비·투자·화폐수요 함수의 반응계수 등으로 결정된다. R,Y 변화는 주어진 곡선 위 이동일 수 있으며 값 자체가 기울기를 결정한다는 말과 다르다. 예를 들어 LM의 R=(k/h)Y-M/(Ph)에서 기울기는k/h다.", "NOTE79쪽 원문 문장·해설 대비, k,h>0 선형 예.", "출판사O의 근거는 Move/Shift 구별이나 원발문은 기울기 결정이라고 달리 진술한다. 잘못된 발문을 그대로 O로 승인하지 않고 X 및 근거를 기록했다.")
short("NOTE-S3C8-Q005", "Y=C(Y-T)+I(R)+G", "소비C는 가처분소득Y-T, 투자I는 금리R의 함수이고 정부지출은G인 폐쇄경제 IS의 재화시장 균형식을 쓰시오.", "생산Y와 소비·투자·정부지출의 합이 같아 Y=C(Y-T)+I(R)+G다. NOTE79쪽 원답 유지.", "폐쇄경제·기본 케인즈 소비/투자 함수.", "수출입항이 없는 원답의 폐쇄경제 전제를 명시했다.", "L330")
short("NOTE-S3C8-Q006", "M/P=L(Y,R)", "명목통화량M, 물가P, 실질화폐수요L(Y,R)인 LM의 화폐시장 균형식을 쓰시오.", "실질공급 M/P와 실질수요 L(Y,R)를 같게 놓는다. NOTE79쪽 원답 분수 복원.", "P>0, 실질화폐수요 정의.", "OCR의 분수기호를 M/P로 복원했다.", "L330")
short("NOTE-S3C8-Q007", "Shift", "전통적 IS에서 다른 조건이 같을 때 정부지출G가 증가하면 IS곡선은 우측으로 Move와 Shift 중 무엇을 하는가?", "주어진 금리에서 수요가 증가해 균형소득이 커지므로 곡선 자체가 우측 Shift한다. NOTE79쪽 원답 유지.", "금리민감투자·양의 안정적 소비승수.", "원해설의 모든 외생변수 증가가 우측이동이라는 일반화는 제외한다. 정부지출에 대해서만 판정한다.", "L330")
short("NOTE-S3C8-Q008", "좌로", "소비가 가처분소득에 증가하는 전통적 IS모형에서 다른 조건이 같을 때 소득세율 인상은 IS를 좌로, 우로 중 어디로 이동시키는가?", "같은 총소득에서 가처분소득·소비가 감소하므로 IS는 좌측 이동한다. NOTE79쪽 원답 유지.", "양의 한계소비성향, 세율 이외 변수 일정.", "소비와 조세의 모형관계를 명시했다.", "L330")
short("NOTE-S3C8-Q009", "Shift", "전통적 LM모형에서 물가·화폐수요함수 일정일 때 명목통화량을 추가 공급하면 LM은 우측으로 Move와 Shift 중 무엇을 하는가?", "실질공급이 늘어 같은 소득에서 더 낮은 금리로 화폐시장 균형이 가능하므로 곡선 자체가 Shift한다. NOTE79쪽 원답 유지.", "통상 우상향 LM.", "원문의 정부라는 표현 대신 통화량 변화 자체를 물어 발권기관을 혼동하지 않게 했다.", "L330")
short("NOTE-S3C8-Q010", "X", "전통적 IS-LM에서 다른 조건이 같을 때 정부지출·조세를 바꾸는 재정정책은 LM을, 명목통화량을 바꾸는 통화정책은 IS를 직접 이동시킨다. O/X?", "반대다. 재정은 IS, 통화는 LM의 직접 이동요인이다. NOTE79쪽 원문의X와 일치한다.", "고정가격·교차피드백을 별도 제외한 직접경로.", "정책수단과 직접 이동을 명시했다.", "L330")
short("NOTE-S3C8-Q011", "물가상승", "우하향 IS·우상향 LM의 비교정태에서 물가상승, 정부지출증가, 통화량증가, 조세감면 중 실질소득Y를 증가시키지 않는 것은?", "물가상승은 M/P 감소로 LM 좌측이동·Y감소를 낳는다. 다른 세 변화는 해당모형에서Y를 높인다. NOTE80쪽 원답 유지.", "모든 비교에서 나머지 변수 고정.", "유동성함정 등 특수구간을 제외한 모형조건을 명시했다.", "L330")
short("NOTE-S3C8-Q012", "구축효과", "확대재정으로 총수요가 증가하지만 이에 따른 금리상승이 민간투자를 줄여 소득증가 효과를 일부 상쇄하는 현상을 무엇이라 하는가?", "제시한 금리상승→민간투자감소 경로가 구축효과다. NOTE80쪽 원문 발문과 답 유지.", "전통적 금리경로 정의.")
short("NOTE-S3C8-Q013", "O", "전통적 고정가격 IS-LM의 통상 구간에서 통화공급확대는 금리를 낮추므로, 금리상승 때문에 민간투자가 위축되는 재정확대형 구축효과가 발생하지 않는다. O/X?", "M/P 증가의 LM우측이동은 금리하락을 뜻하므로 명시된 금리상승 경로가 없다. NOTE80쪽 원답O 유지.", "통상 IS우하향·LM우상향, 다른조건일정.", "원문의 모든 상황에 통화확대 구축이 없다는 단정을 해당 전통모형의 특정경로로 한정했다.", "L330")
short("NOTE-S3C8-Q014", "유동성함정", "전통적 IS-LM에서 LM이 수평이어서 재정확대 시 금리상승에 의한 구축효과가 없는 대표 구간을 무엇이라 하는가?", "유동성함정이다. NOTE80쪽 원답을 유지한다. 금리불변이면 금리경로의 민간투자 위축이 없다.", "수평구간 유지.", "무구축이 가능한 경우가 이것 하나뿐이라는 오해가 없도록 대표 구간을 물었다.", "L331")
short("NOTE-S3C8-Q015", "O", "전통적 고정가격 IS-LM의 유동성함정 수평구간에 머무는 동안 정부지출을 확대하면 금리가 일정한 채 국민소득이 증가할 수 있다. O/X?", "수평 LM과 IS우측이동의 새 교점은 같은금리·더큰소득이다. NOTE80쪽 원답O 유지.", "정부지출 승수양수, 수평구간 유지.", "현실의 모든 재정정책 효과를 최대라고 단정하지 않도록 모형구간을 명시했다.", "L331")
short("NOTE-S3C8-Q017", "피구효과", "물가하락이 보유화폐의 실질가치와 부를 높이고 소비·총수요를 늘릴 수 있다는 실질잔액 경로의 이론 이름은?", "피구효과다. NOTE80쪽 원문 부·소비경로와 정답을 유지한다.", "이론적 실질잔액 소비경로.", "물가하락이 현실에서 반드시 불황탈출을 일으킨다는 보장으로 사용하지 않는다.", "L331")
short("NOTE-S3C8-Q018", "X", "물가신축성에 따른 실질잔액효과라는 소비확대 경로가 존재한다는 사실만으로, 유동성함정에서 재정정책의 독자적 유효성이 반드시 더 강화된다고 결론낼 수 있다. O/X?", "다른 소비확대 경로가 있다는 사실은 재정정책 효과가 반드시 강화된다는 결론을 보장하지 않는다. 원문X는 유지하지만 반대로 모든 재정효과가 반드시 없어진다는 원해설도 성립하지 않는다.", "NOTE80쪽 발문과 해설의 별도검토.", "발문의 단정을 명시하고 원해설의 효과상실 일괄단정도 승인하지 않았다.", "L331")
short("NOTE-S3C8-Q031", "12.5%, 80%", "생산가능인구1,000명, 취업자700명, 실업자100명이다. 실업률과 경제활동참가율을 순서대로 쓰시오.", "경제활동인구800명. 실업률100/800=12.5%, 참가율800/1000=80%. NOTE82쪽 원자료·정답 유지.", "동일 조사대상·기간.", "OCR 훼손된 분수를 복원했다.", "L332")
short("NOTE-S3C8-Q037", "A=명목GDP, B=실질GDP", "GDP디플레이터를 (A/B)×100으로 계산할 때 A와 B는 각각 무엇인가?", "동일 생산의 명목평가를 실질평가로 나눈 가격지수이므로 A명목GDP,B실질GDP다. NOTE82쪽 정답 그대로.", "기준100 가격지수·실질GDP양수·대응기간.", "OCR에서 누락된A/B를 명시적으로 복원했다.")
short("NOTE-S3C8-Q040", "순환주기", "경기저점과 다음 경기저점 사이의 기간을 무엇이라 하는가?", "한 완전한 순환의 길이인 순환주기다. 저점→고점의 확장국면과 구분한다. NOTE83쪽 원문 질문·답 그대로.", "연속한 동일 유형의 전환점 정의.")

mc("S3C8T08-CORE", "②", "주요 국민소득지표 설명 중 적절하지 않은 것은? ① GDP는 국내 생산활동의 부가가치를 합산한 지표이며 평가가격에 맞춘 세금·보조금 조정을 반영한다. ② 실질GNI는 실질GDP에 실질 국외순수취요소소득만 더하면 항상 구해지며 교역조건에 따른 실질무역손익은 고려할 필요가 없다. ③ GNI는 거주자가 생산활동의 대가로 얻은 소득으로, GDP에 국외수취요소소득을 더하고 국외지급요소소득을 뺀다. ④ 명목 국민소득의 생산·분배·지출은 개념상 일치하며 이를 삼면등가라 한다.", "②에는 교역조건 변화의 실질무역손익이 빠졌다. 책의 정답②와 명목/실질구분 의도를 유지한다.③의 국민은 거주자 개념이며④는 명목개념의 삼면등가로 실질구매력 차이와 구별한다.", "TARGET P3 419쪽 네 보기·해설과 BOK강좌 대조.", "③의 국적 중심으로 읽히는 국민/외국인을 거주자/비거주자로 정정하고②는 항상이라는 조건을 명시했다.①평가가격 조정과④명목범위를 명확히 했다.", "L334")
short("NOTE-S3C8-Q026", "3면 등가의 원칙", "명목 국민소득은 생산하여 분배하고 지출하는 세 측면에서 개념상 같은 총액으로 측정된다. 이 원칙은?", "국민소득3면등가다. NOTE81쪽 원문 답 유지. 실제 추계방식 차이에서 생기는 통계상 불일치는 별도 조정문제다.", "동일한 국민계정·명목평가 범위.", "실질소득과 실질생산의 교역조건 차이까지 부정하지 않도록 명목 범위를 명시했다.", "L334")
short("NOTE-S3C8-Q027", "O", "국민계정에서 GNI는 거주자가 생산활동의 대가로 얻은 소득을 측정한다. 명목GDP에 거주자가 국외로부터 받은 요소소득을 더하고 비거주자에게 지급한 요소소득을 뺀다. O/X?", "명목GNI=명목GDP+명목 국외순수취요소소득이므로O다. NOTE81쪽 원답·산식 유지.", "명목 기준·거주자 기준.", "원문 국민/외국인이 국적으로 오인되지 않게 거주자/비거주자로 교정했다. 일반송금 등의 경상이전은 요소소득과 별개다.", "L334")
short("NOTE-S3C8-Q028", "O", "명목GNI=명목GDP+명목 국외순수취요소소득이다. O/X?", "명목 국민총소득 정의와 일치하므로O다. NOTE81쪽 원문 문장·정답 그대로.", "동일기간·통화의 명목국민계정.", "", "L334")
short("NOTE-S3C8-Q029", "교역조건 변화에 따른 실질무역손익, 실질 국외순수취요소소득", "실질GNI=실질GDP+( )+( )의 두 빈칸을 쓰시오.", "실질GDP에 실질무역손익을 더하면 실질GDI, 여기에 실질 국외순수취요소소득을 더하면 실질GNI다. NOTE82쪽 원문 두 항목·정답 유지.", "동일기준 실질국민계정.", "", "L334")

mc("S3C8T09-SUP-02", "②", "통화량2,000조, 실질GDP2,500조, GDP디플레이터0.8(기준1 비율)일 때 통화유통속도는? ①0.50 ②1.0 ③1.25 ④1.60", "MV=PY에서 V=.8×2500/2000=1.0이다. P3 423쪽 실제 문항을 읽어 누락 발문을 복원했고 원문 정답②·수치·보기 유지.", "TARGET P3 423쪽 원페이지; V는 횟수·P는 기준1비율.", "원문 상단 정의의×100은 횟수와백분율 혼동이다. 이 문항의 실제풀이처럼100을 곱하지 않는다.")
mc("MOCK-1-Q092", "④", "전통적 고정가격 IS-LM 설명 중 틀린 것은? ① IS는 재화시장 균형을 이루는 금리·소득의 조합이다. ② LM은 화폐시장 균형을 이루는 금리·소득의 조합이다. ③ 명목통화량과 물가는 LM의 외생변수다. ④ LM이 수직인 경우 확대재정은 금리경로의 무구축효과를 갖는다.", "수직LM이면 소득이 고정되고 IS우측이동은 금리를 높여 재정수요 증가를 민간투자 감소가 상쇄한다. 무구축은 수평LM 구간이므로④다. MOCK25쪽 네 보기·답④ 유지.", "전통적 IS기울기 음·수직LM 극단사례.", "빈 question_text 대신 원본MOCK25쪽 실제92번을 복원했다.", "L330")
mc("MOCK-1-Q093", "②", "전통적 유동성함정 설명에서 틀린 항목을 묶으면? 가. 낮은 임계금리에서 추가공급 화폐가 금리하락 없이 보유될 수 있다. 나. LM이 수직으로 나타난다. 다. 수평구간에 머물러도 재정확대에 완전구축효과가 발생한다. 라. 실질잔액의 소비효과로 탈출경로를 설명하는 이론은 피구효과다. ①가,나 ②나,다 ③다,라 ④가,라", "LM은 수평이고 금리경로의 무구축이므로 나·다가 틀린②다. 가의 추가화폐 흡수와 라의 피구효과는 이론 설명에 부합한다. MOCK25쪽 원문 배열과답 유지.", "고정가격 전통모형과 피구효과의 이론적 논의를 구분.", "원문가의 모두 채권보유를 포기하고 화폐수요가 폭발한다는 단정은 추가화폐 흡수가능성으로 수정했다. 원문 복합선택지 유지.", "L331")
mc("MOCK-2-Q092", "①", "유동성함정 탈출의 전통적 이론을 비교한다. 케인즈적 모형에서는 ( )의 수요확대 경로를, 고전학파의 실질잔액 논의에서는 정책 집행 없이도 ( )에 의한 소비확대 경로를 제시한다. ①확대재정정책,피구효과 ②확대통화정책,피셔효과 ③확대재정정책,피셔효과 ④확대통화정책,피구효과", "수평LM에서 재정확대의 IS우측이동과 실질잔액의 소비효과인 피구효과를 연결한①이다. MOCK52쪽 원문 빈칸·보기·정답 유지.", "현실 효과보장이 아닌 두 이론의 경로 비교.", "원문의 재정정책이 유일하게 반드시 필요하다는 의미로 확대하지 않도록 이론이 제시하는 경로로 명시했다.", "L330 L331")
short("NOTE-S3C8-Q016", "수평, 무한대", "전통적 유동성함정의 극한모형에서 LM은 수직/수평 중 어느 형태이며 화폐수요의 금리탄력성은 교재 표현상 무한대/제로 중 어느 것인가?", "수평 LM·완전탄력적 화폐수요를 가리키므로 수평,무한대다. NOTE80쪽 원문 두 선택쌍과 정답 유지. 금리0에서 로그탄력성 정의가 곤란한 문제와 교재의 극한표현을 구분한다.", "극한·교과서적 완전탄력 수요 의미.", "실제 화폐보유량 자체가 무한하다는 뜻이 아님을 명시했다.", "L331")
short("NOTE-S3C8-Q038", "X", "통화유통속도V는 명목GDP/통화량×100으로 계산되며, 사후추계된다는 사실만으로 경기예측기능이 뛰어나다고 할 수 있다. O/X?", "V=명목GDP/통화량인 회전횟수로×100을 하지 않는다. 그러므로 결합명제는X다. 사후추계라는 사실만으로 예측력이 뛰어나다거나 전혀 없다고 확정할 수도 없다.", "NOTE83쪽 실제38번 원페이지 확인; V=PY/M.", "answer_packets.question_text가 해설38번을 잘못 가져온 것을 원문 발문으로 복원했다. 출판사X는 유지하되 정답근거는 산식오류와 근거없는 예측력 단정을 구분한다.")
short("NOTE-S3C8-Q039", "0.8", "통화량1,000조, 명목GDP800조, 실질GDP500조일 때 통화유통속도는 얼마인가?", "명목GDP/통화량=800/1000=.8회다. 실질GDP는 이 비율에 직접 사용하지 않는다. NOTE83쪽 원문 수치·정답 유지.", "동일기간 명목GDP·대응통화량.")

short("NOTE-S3C8-Q021", "거래적 동기, 예비적 동기, 투기적 동기", "케인즈의 유동성선호설에서 화폐수요를 설명하는 세 가지 동기는?", "일반이론15장의 거래·예비·투기동기다. NOTE81쪽 질문·답 그대로 유지.", "Keynes 원저자의 분류.", "", "L335")
short("NOTE-S3C8-Q022", "O", "케인즈 화폐수요의 단순화된 분해 M=L1(Y)+L2(R)에서 L1은 거래·예비동기의 소득 증가함수, L2는 기대를 고정했을 때 투기동기의 금리 감소함수로 본다. O/X?", "교재의 단순분해와 Keynes 원문의 주된 의존변수 설명에 부합하므로O다. NOTE81쪽 원식·정답 유지.", "주된 의존관계의 단순모형·기대고정.", "원문에서 모든 실제 화폐수요가 두 변수에 배타적으로만 의존한다고 읽히지 않도록 단순모형 전제를 명시했다.", "L335 L330")
short("NOTE-S3C8-Q024", "유동성효과, 소득효과, 피셔효과", "교재의 통화증가 파급 설명에서 초기 화폐공급증가의 금리하락, 소득증가의 화폐수요확대, 기대인플레이션 상승의 명목금리상승이라는 세 경로를 순서대로 무엇이라 하는가?", "각각 유동성효과·소득효과·피셔효과다. NOTE81쪽 원답을 유지하며 P3 417쪽 단계 설명과 대조했다.", "TARGET가 제시한 세경로 설명; 시간순서·크기 보편성 주장 아님.", "통화증가가 실제로 언제나 같은 순서·시차·크기로 세 효과를 만든다는 원문 단정을 경로 명칭 문제로 명확히 했다.")
short("NOTE-S3C8-Q043", "140, 긍정응답 우세", "같은 가중치의 전체응답100개 중 긍정70개·부정30개다. BSI=100+(긍정수-부정수)/전체수×100으로 계산할 때 값과 응답분포의 의미는?", "100+(70-30)/100×100=140이고 긍정응답이 우세하다. NOTE83쪽 값140은 유지한다. 원답 경기상승은 응답방향을 넘어 실제 국면을 확정하는 뜻으로 쓰면 과도하다.", "원문 동일가중 응답수·BSI정의.", "원문 두번째 답 경기상승을 긍정응답우세로 교정하여 실제경기 확정과 심리응답을 구분했다. 수치·계산 의도 유지.", "L336")
short("NOTE-S3C8-Q044", "O(조사응답상 체감경기의 개선이라는 의미)", "같은 조사·비교기준의 업황BSI가80에서90으로 상승했다.100미만이므로 부정응답 우세는 남지만, 응답분포상 체감경기는 전월보다 개선되었다고 해석할 수 있다. O/X?", "동일기준 상승은 긍정·부정 응답의 순차이가 개선됐다는 뜻이다.100미만인지 여부와 전월대비 개선은 서로 다른 정보이므로O다. 한국은행도100미만 지수의 개선추세를 설명한다.", "NOTE83쪽 질문과 출판사X를 BOK정의와 대조; 동일 조사·계절조정 기준.", "출판사 해설은100미만이면 개선 해석 자체가 불가하다고 하여 기준수준과 전월차이를 혼동한다. 답을O로 교정하되 실제GDP확장 확정과 구분했다.", "L336")

mc("S3C8T04-SUP-02", "②", "정부지출 경로가 같고 정액세를 현재 줄이는 대신 미래에 걷는다고 한다. 유동성제약 없는 가계가 미래세 부담을 충분히 고려해 현재 감세분을 저축하여 소비 증가가 상쇄된다는 이론은? ① 피구효과 ② 리카르도의 불변정리 ③ 합리적 기대학파의 정책무용성 정리 ④ 유동성함정이론", "현재감세와 미래증세의 시점변경에 대한 민간저축 상쇄는 리카르도 동등정리이므로②다. TARGET P3 411쪽 네 보기·정답 유지.", "정액세·정부지출경로고정·유동성제약없음 등 모형조건.", "원문 세율인하는 왜곡적 조세의 유인변화를 포함할 수 있어 정액세 시점변경으로 바로잡고, 모든 재정정책이 무효라는 뜻으로 일반화하지 않는다.", "L337")
short("NOTE-S3C8-Q019", "리카르도 동등정리(리카르도 불변정리)", "정부지출 경로가 주어진 상태에서 현재 정액세 감면을 미래 증세로 인식한 가계가 감세분을 저축하여 민간소비가 증가하지 않는다는 이론은? 유동성제약 없음 등 해당 이론의 조건을 전제한다.", "정액세의 부과시점 변화와 민간저축 상쇄라는 리카르도 동등정리다. NOTE80쪽 원문의 세금·저축 경로 및 원답 유지.", "정부지출 동일·미래세부담 내재화·정액세.", "합리적이라는 조건 하나만으로 모든 감세가 무효가 되지 않도록 정리의 전제를 명시했다.", "L337")
mc("S3C8-ADD-07", "④", "투자자가 단기채를 선호해 장기채 보유에 양의 보상을 요구한다는 전통적 유동성프리미엄 이론에 대한 설명 중 틀린 것은? ① 장기수익률을 예상단기금리 평균과 유동성프리미엄의 합으로 근사한다. ② 장·단기채는 불완전 대체관계로 본다. ③ 예상단기금리 경로가 일정해도 양의 만기프리미엄으로 우상향 곡선을 설명할 수 있다. ④ 이 이론이 전제한 장기보유 보상은 양수와 음수가 모두 가능하다.", "이 문항의 전통적 단기선호 가정은 장기보유에 양의 보상을 요구하므로 그 보상을 음수도 가능하다고 한④가 틀리다. TARGET P3 428~429쪽 원답④ 유지. 실제 시장의 일반적 기간프리미엄 부호와는 구별한다.", "교재가 정의한 단기선호·양의유동성보상 이론에 한정. 산술평균 표현은 근사.", "원문③의 가장 잘 설명이라는 절대순위를 구체적인 우상향 가능성으로 명확히 했다. 원문 네 보기의 기간수익·대체관계·곡선·프리미엄 부호 주제를 유지했다.")
short("NOTE-S3C8-Q033", "X", "학생이나 전업주부라는 신분만으로, 조사기간의 취업·구직·취업가능 여부와 관계없이 모두 비경제활동인구로 분류한다. O/X?", "취업한 학생은 취업자로 경제활동인구에 포함되는 반례가 있다. 비경제활동 여부는 신분명만으로 결정되지 않으므로X다. NOTE82쪽 원문의 일괄분류를 교정한다.", "고용통계의 조사기간 취업·실업 분류를 충족하는 경우.", "원답O는 통상 예시를 예외없는 규칙으로 표현했다. 신분만으로 전원을 제외하는 명제는X로 교정하며 구직단념자의 통계적 정의와도 구분한다.", "L332")
short("NOTE-S3C8-Q041", "O", "구성지표의 증가·불변·감소 방향만 집계한 경기확산지수는 변화가 얼마나 넓게 퍼졌는지 보여주지만, 개별변화의 크기를 직접 반영해 경기 진폭·속도를 측정하는 지수는 아니다. O/X?", "증가항목들의 실제 증가율이1%든10%든 방향만 같으면 같은 확산값이 나온다. 따라서 크기를 직접 측정하지 않는다는O는 타당하다. NOTE83쪽 원답 유지.", "방향집계식 확산지수; 크기와 방향의 구별.", "전환점파악에 유용하다는 설명을 실제 전환점 확정 보장으로 읽히지 않게 확산정보로 명확히 했다. CI하락만으로 경기수축 확정이라는 부가해설은 승인하지 않는다.")
short("NOTE-S3C8-Q042", "X", "증가지표를1, 불변을0.5, 감소를0으로 점수화해 평균×100으로 계산하는 경기확산지수다. 지수가40이라는 사실만으로 실제 국민경제의 경기확장 국면이 확정된다. O/X?", "40은 증가방향의 가중비중이 절반보다 작다는 뜻이고 실제 경기확장 국면 확정을 뜻하지 않는다. 따라서 원문X를 유지한다. 반대로 이 값 하나로 실제 수축을 확정하는 해설도 과도하다.", "NOTE83쪽, 확산지수 산식을 명시.", "50기준의 방향확산 신호와 실제경기 판정을 구분했다.")

mc("S3C8-ADD-04", "②", "케인즈의 단순화된 M=L1(Y)+L2(R)에서 주로 소득Y에 의존하는 L1에 묶는 화폐수요 동기는? ㄱ거래적 동기 ㄴ예비적 동기 ㄷ투기적 동기. ①ㄱ ②ㄱ,ㄴ ③ㄱ,ㄴ,ㄷ ④정답없음", "거래·예비동기가L1(Y)에 묶이고 투기동기는L2(R)이므로②다. P3 428쪽 이미지의 네 조합과 원답②를 직접 확인했다.", "Keynes 원문과 TARGET의 단순화된 함수분해.", "OCR에서 누락된②ㄱ,ㄴ을 이미지로 복원했다. 현실의 금리영향 완전배제 규칙으로 읽히지 않게 주로라는 범위를 명시했다.", "L335")
mc("S3C8T09-CORE", "④", "2026년3월 산업활동동향의 공식 선행종합지수 구성지표에 포함되지 않는 것은? ① 재고순환지표 ② 경제심리지수 ③ 코스피지수 ④ CP유통수익률", "공식 선행7개에①②③은 들어가지만④는 없다. 원문 P3 422쪽 이미지의 보기·정답④를 유지한다.", "2026-04-30 발표 공식구성표; 2026-10-13 검토범위.", "원문 '예측에 사용할 수 없는'을 해설이 의도한 공식 선행지표 구성 여부로 최소교정했다. 후행분류는 예측정보가 전혀 없다는 뜻이 아니며 이 승인에서는 CP의 후행구성 여부를 별도 확정하지 않는다.", "L338")
mc("MOCK-2-Q095", "②", "2026년3월 산업활동동향의 공식 선행종합지수 구성지표인 것은? ① 건설기성액 ② 재고순환지표 ③ 광공업생산지수 ④ CP유통수익률", "재고순환지표가 선행구성표에 있으므로②다.①③은 동행구성에 있으며④는 선행7개에 없다. MOCK53쪽 원보기와 정답② 유지.", "공식 분류기준.", "원문의 예측에 사용할 수 있는지라는 과도하게 넓은 발문을 출제의도인 선행구성 여부로 명확히 했다. 다른 지표도 예측분석에 활용할 가능성까지 배제하지 않는다.", "L338")
short("NOTE-S3C8-Q034", "선행종합지수, 동행종합지수", "2026년3월 산업활동동향의 구성분류에서 기계류내수출하지수(선박제외)와 내수출하지수는 각각 어느 경기종합지수에 들어가는가?", "기계류내수출하(선박제외)는 선행, 내수출하는 동행구성표에 있다. NOTE82쪽 원문 두 빈칸·정답 유지.", "공식 구성·지표명의 범위.", "기계류 지표의 선박제외 조건과 확인자료의 기준을 명시했다.", "L338")
short("NOTE-S3C8-Q035", "선행종합지수, 동행종합지수", "2026년3월 산업활동동향에서 건설수주액과 건설기성액은 각각 어느 경기종합지수의 구성지표인가?", "건설수주는 선행, 이미 수행된 건설기성은 동행구성표에 있다. NOTE82쪽 질문·정답 유지.", "공식 구성분류.", "확인한 자료 기준을 명시했다.", "L338")
short("NOTE-S3C8-Q032", "군인, 형이 확정된 교도소 수감자", "경제활동인구조사의15세이상 조사대상에서 제외되는 집단 중, 교재가 두 빈칸으로 든 병역 복무 집단과 형 확정 수감 집단은? 이 둘이 제외대상 전부라는 뜻은 아니다.", "군인(직업군인·상근예비역 포함)과 형이 확정된 교도소 수감자다. NOTE82쪽 원답 군인·재소자의 의도를 유지한다. 사회복무요원 등 다른 제외대상도 공식표에 있다.", "2024 통계품질진단의 조사대상 설명.", "원문 생산가능인구 전체정의를 단 두 집단 제외로 완결한 표현을 해당 조사 제외집단 예시로 교정했다. 미결수 등까지 재소자라는 말로 일괄확장하지 않는다.", "L339")

mc("MOCK-2-Q093", "④", "TARGET에서 다음처럼 저축·투자·정부적자와 화폐잔액의 기간 중 변화를 함께 놓은 이자율결정이론을 무엇이라 부르는가? 저축+화폐공급의 변동=투자+정부예산적자+화폐수요의 변동. ① 고전학파의 이자율결정이론 ② 빅셀의 이자율결정이론 ③ 케인즈의 유동성선호이론 ④ 현대적 대부자금설", "화폐공급과 수요의 잔액 자체가 아닌 같은 기간의 변동을 저축·투자 유량에 합하여 자금 공급·수요를 비교한다. TARGET MOCK52쪽 공식·4보기와75쪽 해설의 명칭은 현대적 대부자금설이므로④다. 이 검토는 책에서 주어진 모형의 명칭과 유량 차원 일치에 한정하며 모형의 현실 예측력이나 이론의 역사적 최초성은 입증하지 않는다.", "같은 기간의 유량, 동일 화폐단위, TARGET에 명시된 모형 명칭을 확인하는 정의 문제.", "모든 경제에서 성립하는 이자율의 유일한 결정법칙으로 오해하지 않게 교재의 모형 정의 범위를 명시했다.")
short("NOTE-S3C8-Q020", "예상치 못한 화폐공급", "가격이 조정되고 생산의 일시적 이탈을 Y-Y*=a(P-Pe), a>0로 설명하는 화폐착각 모형을 전제로 한다. 합리적 기대 아래 물가의 예상오차를 만드는 (예상된 화폐공급 / 예상치 못한 화폐공급) 확대가 생산을 일시적으로 촉진할 수 있는가?", "예상된 물가상승이면 P=Pe로 산출 이탈이0이다. 예상하지 못한 확대가 P>Pe를 만들면 a(P-Pe)>0이므로 일시적으로 생산이 증가한다. 따라서 원문 두 선택지와 답인 예상치 못한 화폐공급을 유지한다. 합리적 기대만으로 이 결론을 도출하지 않으며 물가경직성 모형으로 일반화하지 않는다.", "NOTE81쪽 원문 두 선택지; a>0, 예상오차 공급함수, 확대가 양의 물가 예상오차를 만드는 조건.", "원문의 합리적 기대학파 전체에 대한 무조건적 일반화를 피하려고 결론에 필요한 공급함수와 일시적 효과 조건을 명시했다. 반복되는 충격이면 반드시 완전히 예측된다는 원해설 단정은 승인하지 않는다.")
short("NOTE-S3C8-Q023", "유동성선호이론 / 불편기대이론", "현재 및 미래의 예상 단기금리가 모두 일정하다고 가정한다. 만기에 따라 커지는 양의 기간프리미엄으로 우상향 수익률곡선을 설명하는 것은 (유동성선호이론 / 불편기대이론) 중 무엇이며, 기간프리미엄이 없는 순수 기대가설로는 같은 조건에서 우상향을 설명할 수 있는가? 이론 이름을 순서대로 쓰시오.", "일정한 예상 단기금리 r에 프리미엄 p(n)>0가 만기 n에 따라 증가하면 장기금리의 근사 r+p(n)는 우상향한다. 프리미엄0의 순수기대가설에서는 예상 단기금리 평균이r로 일정하여 같은 조건의 곡선은 평탄하다. 원문 답 두 이론의 순서를 유지한다. 미래 단기금리 상승이 예상되면 불편기대이론만으로도 우상향이 가능하다.", "NOTE81쪽 두 이론 비교; 동일한 일정 예상 단기금리 경로, 순수기대의 프리미엄0, 유동성선호의 만기별 증가프리미엄. 평균금리 관계는 근사로 사용.", "원문의 불편기대이론은 우상향을 설명하지 못한다는 무조건 단정을 특정 기대경로 조건으로 최소 교정하고 '가장 잘'이라는 기준 없는 평가를 제거했다.")
